import { ChainDataError } from './client.js';

export const ZERO_ADDRESS = '0x0000000000000000000000000000000000000000';
export const bigintJSON = value => JSON.parse(JSON.stringify(value, (_, item) => typeof item === 'bigint' ? item.toString() : item));
export function playerAddress(value) {
  if (!/^0x[0-9a-f]{40}$/i.test(value ?? '')) throw new ChainDataError('Invalid player address.', 'INVALID_REQUEST');
  return value.toLowerCase();
}
export function uint(value, maximum = 0xffffff) {
  const n = Number(value);
  if (value == null || value === '' || !Number.isSafeInteger(n) || n < 0 || n > maximum) throw new ChainDataError('Invalid numeric parameter.', 'INVALID_REQUEST');
  return n;
}
export async function fields(snapshot, contract, names, ...keys) {
  return Object.fromEntries(await Promise.all(names.map(async name => [name, await snapshot.field(contract, name, ...keys)])));
}
export async function calls(snapshot, contract, methods, args = []) {
  return Object.fromEntries(await Promise.all(methods.map(async method => [method, await snapshot.call(contract, method, args)])));
}

export async function gameState(s) {
  const [state, views] = await Promise.all([
    fields(s, 'GAME', ['level', 'dailyIdx', 'jackpotPhaseFlag', 'gameOver', 'decWindowOpen', 'rngLockedFlag',
      'phaseTransitionActive', 'ticketWriteSlot', 'ticketsFullyProcessed', 'prizePoolFrozen', 'jackpotCounter', 'purchaseStartDay', 'jackpotFlags']),
    calls(s, 'GAME', ['mintPrice', 'futurePrizePoolView', 'nextPrizePoolView', 'currentPrizePoolView', 'claimablePoolView']),
  ]);
  const day = Number(state.dailyIdx);
  const word = day ? await s.call('GAME', 'rngWordForDay', [day]) : 0n;
  const { anchor, period, deployDayBoundary } = s.client.clock;
  return {
    ...bigintJSON(state), level: Number(state.level), jackpotCounter: Number(state.jackpotCounter), ticketWriteSlot: Number(state.ticketWriteSlot),
    // jackpotFlags bit 0 (JACKPOT_TURBO) = one-day phase, else JACKPOT_DAYS = 3; bit 1 is the
    // post-turbo coinflip bonus latch.
    jackpotFlags: Number(state.jackpotFlags), jackpotDays: (Number(state.jackpotFlags) & 1) ? 1 : 3,
    phase: state.gameOver ? 'GAMEOVER' : state.jackpotPhaseFlag ? 'JACKPOT' : 'PURCHASE',
    price: String(views.mintPrice),
    levelStartTime: state.purchaseStartDay ? String((deployDayBoundary + Number(state.purchaseStartDay) - 1) * period + anchor) : null,
    prizePools: { futurePrizePool: String(views.futurePrizePoolView), nextPrizePool: String(views.nextPrizePoolView),
      currentPrizePool: String(views.currentPrizePoolView), claimableWinnings: String(views.claimablePoolView), frozen: state.prizePoolFrozen },
    dailyRng: word ? { day, finalWord: String(word) } : null,
    blockNumber: String(s.block.number), blockHash: s.block.hash,
  };
}

export function scoreBreakdown(b) {
  return { totalBps: Number(b.total), mintLevelStreakPoints: Number(b.mintStreakPoints), questStreakPoints: Number(b.questStreak), questStreakCreditedPoints: Number(b.questStreakPoints),
    mintCountPoints: Number(b.mintCountPoints), affiliatePoints: Number(b.affiliatePoints), cursePoints: Number(b.cursePoints),
    passBonus: b.passBonusPoints ? { kind: b.deityPass ? 'deity' : Number(b.passBonusPoints) >= 40 ? 'whale_100' : 'whale_10', points: Number(b.passBonusPoints) } : null };
}

// Current balances and quest state never wait for event history. Lifetime
// aggregates are separate, on-demand history projections; null means unread.
export async function playerState(s, rawAddress) {
  const player = playerAddress(rawAddress); const game = s.client.address('GAME');
  const [state, score, sub, quest, levelQuest, shields, balances, flip, auto, referral, code, nonce] = await Promise.all([
    gameState(s), s.call('GAME_LENS', 'activityScoreBreakdown', [game, player]), s.call('GAME_LENS', 'subInfoFull', [game, player]),
    s.call('QUESTS', 'getPlayerQuestView', [player]), s.call('QUESTS', 'getPlayerLevelQuestView', [player]), s.call('QUESTS', 'shieldsOf', [player]),
    Promise.all(['COIN', 'DGNRS', 'SDGNRS', 'WWXRP'].map(name => s.call(name, 'balanceOf', [player]))),
    calls(s, 'COINFLIP', ['coinflipAmount', 'previewClaimCoinflips'], [player]), s.call('COINFLIP', 'coinflipAutoRebuyInfo', [player]),
    s.call('AFFILIATE', 'getReferrer', [player]), s.field('AFFILIATE', 'playerReferralCode', player), s.field('GAME', 'degeneretteBetNonce', player),
  ]);
  const [claimable, bounty, biggest, ownCode] = await Promise.all([
    s.call('GAME', 'claimableWinningsOf', [player]), s.call('COINFLIP', 'recordPool'), s.call('COINFLIP', 'biggestFlipEver'),
    s.call('AFFILIATE', 'defaultCode', [player]),

  ]);
  return {
    player, day: s.client.dayAt(s.block.timestamp), blockNumber: String(s.block.number), blockHash: s.block.hash, historicalUnavailable: false,
    scoreBreakdown: scoreBreakdown(score), dailyActivity: null, claimableEth: String(claimable),
    totalClaimed: null, totalCredited: null, totalAffiliateEarned: null,
    flipBalance: String(balances[0]), dgnrsBalance: String(balances[1]), sdgnrsBalance: String(balances[2]), wwxrpBalance: String(balances[3]),
    currentStreak: Number(score.questStreak), shields: Number(shields.shields), afkingActive: sub.active,
    quests: quest.quests.map((q, slot) => ({ day: Number(q.day), slot, questType: Number(q.questType),
      progress: String(quest.progress[slot]), target: String(q.requirements.mints || q.requirements.tokenAmount),
      completed: quest.completed[slot], highDifficulty: q.highDifficulty,
      requirementMints: Number(q.requirements.mints), requirementTokenAmount: String(q.requirements.tokenAmount) })),
    levelQuest: { questType: Number(levelQuest.questType), progress: String(levelQuest.progress), target: String(levelQuest.target),
      completed: levelQuest.completed, eligible: levelQuest.eligible, progressAvailable: true },
    questStreak: { baseStreak: Number(score.questStreak), lastCompletedDay: Number(quest.lastCompletedDay) },
    decimatorClaims: null,
    coinflip: { depositedAmount: String(flip.coinflipAmount), claimablePreview: String(flip.previewClaimCoinflips),
      autoRebuyCarry: String(auto.carry), autoRebuyEnabled: auto.enabled, autoRebuyStop: String(auto.stop),
      currentBounty: String(bounty), biggestFlipPlayer: null, biggestFlipAmount: String(biggest) },
    decimator: { windowOpen: state.decWindowOpen, activityScore: Number(score.total), claimablePerLevel: null, futurePoolTotal: state.prizePools.futurePrizePool },
    terminal: null, degenerette: { betNonce: Number(nonce), pendingBets: null },
    affiliate: { referrer: referral === ZERO_ADDRESS ? null : referral, code, ownCode, referralCount: null },
    tickets: null, spendSummary: null,
  };
}
